function drawSnorlaxSoftGiant(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 1.6;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.06 * breathSin;
  const sX = 1.0 - 0.03 * breathSin;
  const by = 0;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 32 * (1.0 - 0.15 * breathSin), 8, 0, 0, Math.PI * 2); ctx.fill();

  // Thân xanh
  ctx.fillStyle = '#0e7490';
  ctx.beginPath(); ctx.ellipse(0, by + 14, 28 * sX, 22 * sY, 0, 0, Math.PI * 2); ctx.fill();
  // Bụng kem
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.ellipse(0, by + 15, 20 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Chân
  ctx.beginPath(); ctx.arc(-22, by + 30, 10, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(22,  by + 30, 10, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#a16207';
  ctx.beginPath(); ctx.arc(-22, by + 30, 6, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(22,  by + 30, 6, 0, Math.PI * 2); ctx.fill();

  // Đầu
  ctx.fillStyle = '#0e7490';
  ctx.beginPath(); ctx.ellipse(0, by - 12, 20 * sX, 14 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.ellipse(0, by - 11, 14 * sX, 10 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Tai
  ctx.fillStyle = '#0e7490';
  ctx.beginPath(); ctx.moveTo(-16, by - 20); ctx.lineTo(-22, by - 34); ctx.lineTo(-8, by - 22); ctx.fill();
  ctx.beginPath(); ctx.moveTo(8,   by - 22); ctx.lineTo(22,  by - 34); ctx.lineTo(16, by - 20); ctx.fill();

  // Mắt & miệng
  ctx.strokeStyle = '#0f172a';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(-10, by - 13); ctx.lineTo(-4, by - 13);
  ctx.moveTo(4,   by - 13); ctx.lineTo(10, by - 13);
  ctx.moveTo(-6,  by - 7);  ctx.lineTo(6,  by - 7);
  ctx.stroke();

  // Răng
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.moveTo(-5, by - 7); ctx.lineTo(-4, by - 10); ctx.lineTo(-3, by - 7); ctx.fill();
  ctx.beginPath(); ctx.moveTo(3,  by - 7); ctx.lineTo(4,  by - 10); ctx.lineTo(5,  by - 7); ctx.fill();

  // Tay
  ctx.fillStyle = '#0e7490';
  ctx.beginPath(); ctx.roundRect(-30, by + 8, 10, 16, 5); ctx.fill();
  ctx.beginPath(); ctx.roundRect(20,  by + 8, 10, 16, 5); ctx.fill();

  ctx.restore();
}
